namespace org.elasticsearch.plugin.analysis.lsh;



using org.apache.lucene.analysis;
using org.apache.lucene.analysis.tokenattributes;
using org.elasticsearch.plugin.analysis.lsh.LSHBinner;

using generic.lsh.vector;
using ghidra.features.bsim.query.elastic;

public class LSHTokenizer : Tokenizer {
    private CharTermAttribute bytesAtt = addAttribute(typeof(CharTermAttribute));
    private BytesRef[] tokens;
    private int pos;				// Number of terms/tokens returned so far
    private Base64VectorFactory vectorFactory;
    private LSHBinner binner;
    private char[] vecBuffer;

    public LSHTokenizer(int k,int L,Base64VectorFactory vFactory) : base(DEFAULT_TOKEN_ATTRIBUTE_FACTORY)
    {
    	vectorFactory = vFactory;
    	binner = new LSHBinner();
    	binner.setKandL(k, L);
    	pos = -1;
    	vecBuffer = Base64VectorFactory.allocateBuffer();
    }

	/* @Override */
	public bool incrementToken()
    {
		clearAttributes();
		if (pos < 0) {
			LSHVector vector = vectorFactory.restoreVectorFromBase64(input,vecBuffer);
//			AnalysisLSHPlugin.settingString = AnalysisLSHPlugin.settingString + " : " + Long.toHexString(vector.calcUniqueHash());
			binner.generateBinIds(vector.getEntries());
			tokens = binner.getTokenList();
			pos = 0;
		}
		if (pos < tokens.length) {
			char[] buffer = tokens[pos].buffer;
			bytesAtt.copyBuffer(buffer,0,buffer.length);
			pos += 1;
			return true;
		}
		return false;
	}

	/* @Override */
	public void reset()
    {
		base.reset();
		pos = -1;
	}
}
